                        print(f'FOUND:',d0,d1,d2,d3)
                        return r, [d0,d1,d2,d3]
    return None, []

if __name__ == '__main__':
    b = int(sys.argv[1]) if len(sys.argv)>1 else 10
    r, last4 = find_selfdescriptive(b)
    if r:
        print('last 4:',last4)
        print('value:',r)
