from collections import Counter
import sys

def selfdesc_digits(b):
    # For huge bases, try the known construction (sequence A098113): [0]*(b-4)+[2,1,2,0]
    if b < 4:
        return None
    guess = [0]*(b-4)+[2,1,2,0]
    if len(guess) != b:
        return None
    c = Counter(guess)
    for i in range(b):
        if guess[i] != c[i]:
            return None
    return guess

def check(b, digits):
    c = Counter(digits)
    for idx, d in enumerate(digits):
        if d != c[idx]:
            return False
    return True

def main():
    if len(sys.argv) < 2:
        print("Usage: selfdesc_solver.py <base>")
        return
    b = int(sys.argv[1])
    digits = selfdesc_digits(b)
    if digits and check(b, digits):
        print("".join(map(str, digits)))
    else:
        print(f"No self-descriptive found for base {b}")
        sys.exit(1)

if __name__ == "__main__":
    main()

