#!/usr/bin/env python3
# Brute force generator for b-digit self-descriptive number for arbitrary base b >= 2000
# Forgo OEIS, instead implement the challenge check logic and search for a valid r.
from collections import defaultdict, Counter

def check(b, r):
    dic = defaultdict(int)
    t = r
    for i in range(b):
        dic[b-i-1] = t % b
        t = t // b
    count = Counter(dic.values())
    count = defaultdict(int,count)
    for i,j in dic.items():
        if dic[i] != count[i]:
            return False
    return t == 0

def find_selfdesc(b):
    # Try OEIS formula first, then brute force nearby
    # OEIS: digits = [0]*(b-4) + [2, 1, 2, 0]
    digits = [0]*(b-4) + [2, 1, 2, 0]
    t = 0
    for d in digits:
        t = t * b + d
    if check(b, t):
        return t
    # If not, try incrementing the last few digits
    from itertools import product
    for last4 in product(range(b), repeat=4):
        d = [0]*(b-4) + list(last4)
        t = 0
        for x in d:
            t = t * b + x
        if check(b, t):
            return t
    return None

if __name__ == '__main__':
    import sys
    b = int(sys.argv[1])
    ans = find_selfdesc(b)
    print(ans)

