        return int(m.group(1))
    else:
        raise Exception("Could not find b in chall.py")

def try_send(r):
    try:
        conn = remote(HOST, PORT)
        recv = b""
        # Read until input prompt or EOF
        while True:
            chunk = conn.recv(timeout=2)
            if not chunk:
                break
            recv += chunk
            if b'number' in recv.lower():
                break
        conn.sendline(str(r).encode())
        resp = conn.recvall(timeout=2).decode(errors='replace')
        conn.close()
        return recv.decode(errors='replace'), resp
